    internal static string Get(string language,string key)
    {
        if(language=="es-MX")language="es";
        string[] row;int index=Array.IndexOf(Keys,key);
        if(index>=0 && Rows.TryGetValue(language??"en",out row) && index<row.Length)return row[index];
        return LauncherLocalization.Text(language??"en",key);
    }
